package pagos;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.fasterxml.jackson.databind.ObjectMapper;import config.ConfiguracionMercadoPago;import java.util.Map;import org.junit.jupiter.api.Test;
class PreflightMercadoPagoTest {private ConfiguracionMercadoPago cfg(){return ConfiguracionMercadoPago.desde(Map.of("MP_ENABLED","true","MP_ACCESS_TOKEN","APP_USR-test","MP_WEBHOOK_SECRET","y","MP_PUBLIC_BASE_URL","https://club.example","MP_TEST_USER_ID","123"));}@Test void identidadCoincidenteHabilitaSandbox(){MercadoPagoHttpTransport h=mock(MercadoPagoHttpTransport.class);when(h.ejecutar(eq("GET"),any(),anyMap(),isNull())).thenReturn(new MercadoPagoHttpTransport.Respuesta(200,"{\"id\":123}"));assertTrue(new PreflightMercadoPago(h,new ObjectMapper()).verificar(cfg()).valido());}@Test void identidadDistintaFallaCerrado(){MercadoPagoHttpTransport h=mock(MercadoPagoHttpTransport.class);when(h.ejecutar(eq("GET"),any(),anyMap(),isNull())).thenReturn(new MercadoPagoHttpTransport.Respuesta(200,"{\"id\":999}"));assertEquals("IDENTIDAD_NO_COINCIDE",new PreflightMercadoPago(h,new ObjectMapper()).verificar(cfg()).estado());}@Test void errorExternoFallaCerrado(){MercadoPagoHttpTransport h=mock(MercadoPagoHttpTransport.class);when(h.ejecutar(eq("GET"),any(),anyMap(),isNull())).thenReturn(new MercadoPagoHttpTransport.Respuesta(401,"{}"));assertFalse(new PreflightMercadoPago(h,new ObjectMapper()).verificar(cfg()).valido());}}
